  function activityColor(name){var value=String(name||'').trim().toLowerCase();if(!value)return'#e8c9a0';var hash=2166136261;Array.from(value).forEach(function(character){hash^=character.codePointAt(0);hash=Math.imul(hash,16777619);});hash>>>=0;var hue=hash%360,saturation=58+((hash>>>8)%13),lightness=72+((hash>>>16)%7),s=saturation/100,l=lightness/100,chroma=(1-Math.abs(2*l-1))*s,x=chroma*(1-Math.abs((hue/60)%2-1)),match=l-chroma/2,r=0,g=0,b=0;if(hue<60){r=chroma;g=x;}else if(hue<120){r=x;g=chroma;}else if(hue<180){g=chroma;b=x;}else if(hue<240){g=x;b=chroma;}else if(hue<300){r=x;b=chroma;}else{r=chroma;b=x;}return'#'+[r,g,b].map(function(channel){return Math.round((channel+match)*255).toString(16).padStart(2,'0');}).join('');}
