  async function createCategory(){var name=String(byId('calendarCategoryName').value||'').trim(),color=byId('calendarCategoryColor').value;if(!name){status('请填写分类名称',true);return;}try{await readJson(await request('/api/admin/calendar/categories',{method:'POST',body:JSON.stringify({name:name,color:color,sortOrder:(categories.length+1)*10})}));byId('calendarCategoryName').value='';await loadCategories();status('分类已新增。');}catch(error){status(error.message,true);}}
  async function editCategory(category){var name=prompt('分类名称',category.name);if(name===null)return;name=String(name).trim();if(!name)return;var color=prompt('分类颜色（#RRGGBB）',category.color);if(color===null)return;try{await readJson(await request('/api/admin/calendar/categories/'+category.id,{method:'POST',body:JSON.stringify({name:name,color:String(color).trim()})}));await loadCategories();status('分类已更新。');}catch(error){status(error.message,true);}}
  async function changeCategoryStatus(category,button){var originalText=button&&button.textContent;if(button){button.disabled=true;button.textContent='处理中…';}try{var data=await readJson(await request('/api/admin/calendar/categories/'+category.id+'/status',{method:'POST',body:JSON.stringify({enabled:!category.enabled})}));await loadCategories();var enabled=!!(data.category&&data.category.enabled);status(enabled?'分类已启用，所属日程已恢复公开显示。':'分类已停用，所属日程已从公开日历隐藏；重新启用后会恢复显示。');}catch(error){status(error.message,true);}finally{if(button&&button.isConnected){button.disabled=false;button.textContent=originalText;}}}
