  function updateFormVisibility(){var structure=byId('calendarScheduleType').value,mode=byId('calendarDateMode').value,isComposite=structure==='composite',isList=mode==='list'&&!isComposite;byId('calendarDateModeGroup').hidden=isComposite;byId('calendarDateListGroup').hidden=!isList;byId('calendarDurationGroup').hidden=isList;byId('calendarEndDateGroup').hidden=isList;byId('calendarStartDate').closest('.form-group').hidden=isList;byId('calendarDateQuickActions').hidden=isList;byId('calendarCompositeFields').hidden=!isComposite;byId('calendarRepeatSection').hidden=isList;byId('calendarRecurrenceFields').hidden=isList||!byId('calendarRepeatEnabled').checked;syncStructureCards();syncCompositeEditor();updateRecurrenceVisibility();renderDatePreview();}
