  async function savePreviewEdit(event){event.preventDefault();var schedule=schedules.find(function(item){return item.id===Number(byId('calendarPreviewEditId').value);});if(!schedule)return;var name=String(byId('calendarPreviewEditName').value||'').trim();if(!name){byId('calendarPreviewEditName').focus();return;}var body={scope:byId('calendarPreviewEditScopeGroup').hidden?'all':byId('calendarPreviewEditScope').value,occurrenceDate:byId('calendarPreviewEditOccurrenceDate').value,name:name,color:byId('calendarPreviewEditAutoColor').checked?null:byId('calendarPreviewEditColor').value,fontBold:byId('calendarPreviewEditBold').checked,enabled:byId('calendarPreviewEditEnabled').checked};await readJson(await request('/api/admin/calendar/schedules/'+schedule.id+'/quick-edit',{method:'POST',body:JSON.stringify(body)}));byId('calendarPreviewEditDialog').close();await loadSchedules();status(body.scope==='all'?'整个循环日程已更新。':body.scope==='single'?'仅当前这一次已更新。':'当前及以后的循环已更新。');}
  function helpText(label){var text=String(label||'').replace(/\s+/g,'').replace(/[？?]/g,'');var rules=[['日期方式','连续时段适合连续活动；多个不连续日期适合分散开放的活动。'],['开始日期','一次活动第一次出现的日期；重复日程会以它作为循环锚点。'],['持续天数','每次活动连续占用的天数，结束日期会自动计算。'],['循环单位','选择按天、按周或按月重复。'],['每隔','例如选择“周”并填写 2，表示每两周重复一次。'],['星期','1 至 7 分别表示周一至周日，可用逗号填写多个日期。'],['结束方式','长期循环会在可查看的前后一年动态铺开；截止日期和循环次数会限制发生范围。'],['展示方式','甘特任务块适合跨日阶段；每日清单适合每天分别展示任务。'],['偏移','偏移 0 代表主活动首日，偏移 1 代表第二天。'],['活动分类','决定公开日历左侧显示在哪个分类中。'],['活动颜色','默认根据活动名称生成固定颜色：同名同色、不同名自动分配；取消自动配色后可以手动指定。'],['说明','用户点击活动块后会看到这里填写的内容。'],['时间','可选；用于补充当天具体开始和结束时间。']];var found=rules.find(function(rule){return text.indexOf(rule[0])>=0;});return found?found[1]:'该选项会影响日程的保存规则和公开日历展示；如不确定，可保留默认值后查看底部预览。';}
  function decorateCalendarHelp(){Array.from(document.querySelectorAll('#calendarScheduleForm .form-group>label:not(.calendar-switch):not(.time-checkbox-group)')).forEach(function(label){if(label.querySelector('.calendar-help-trigger'))return;var title=label.textContent.trim(),button=document.createElement('button');button.type='button';button.className='calendar-help-trigger';button.textContent='?';button.setAttribute('aria-label',title+'说明');button.dataset.helpTitle=title;button.dataset.helpText=helpText(title);label.appendChild(button);});}
  async function scheduleAction(schedule,action){if(action==='edit'){editSchedule(schedule);return;}if(action==='delete'&&!confirm('确定删除“'+schedule.name+'”吗？'))return;var url='/api/admin/calendar/schedules/'+schedule.id,options={method:'POST'};if(action==='copy')url+='/copy';if(action==='status'){url+='/status';options.body=JSON.stringify({enabled:!schedule.enabled});}if(action==='delete')options={method:'DELETE'};try{await readJson(await request(url,options));await loadSchedules();status('日程操作成功。');}catch(error){status(error.message,true);}}
  function renderPresets(){var host=byId('calendarPresetList');if(!host)return;if(!presets.length){host.innerHTML='<div class="admin-status">暂无预设，可在编辑器底部保存。</div>';return;}host.innerHTML=presets.map(function(preset){return '<div class="calendar-admin-row" data-preset-id="'+escapeHtml(preset.id)+'"><strong>'+escapeHtml(preset.name)+'</strong><div class="admin-status">'+escapeHtml(preset.payload&&preset.payload.name||'未命名日程')+'</div><div class="calendar-preset-actions"><button class="btn secondary" type="button" data-preset-action="apply">套用</button><button class="btn secondary" type="button" data-preset-action="delete">删除</button></div></div>';}).join('');}
  async function savePreset(){var payload=schedulePayload();if(!payload.name){status('请先填写日程内容，再保存预设。',true);return;}var name=prompt('预设名称',payload.name+'预设');if(name===null)return;name=String(name).trim();if(!name)return;try{await readJson(await request('/api/admin/calendar/presets',{method:'POST',body:JSON.stringify({name:name,payload:payload})}));await loadPresets();status('预设已保存到服务器。');}catch(error){status(error.message,true);}}
