  function renderAdminPreview(){var host=byId('calendarAdminPreview');if(!host)return;var from=previewAnchor||defaultPreviewAnchor(),days=previewDays,dates=Array.from({length:days},function(_,i){return addDays(from,i)}),today=todayText(),ordered=schedules.slice().sort(function(a,b){return Number(a.category&&a.category.sortOrder||0)-Number(b.category&&b.category.sortOrder||0)||Number(a.sortOrder||0)-Number(b.sortOrder||0)}),map=new Map();previewOccurrences.forEach(function(x){if(!map.has(x.scheduleId))map.set(x.scheduleId,[]);map.get(x.scheduleId).push(x)});var groups=new Map();ordered.forEach(function(x){var k=x.category&&x.category.id||'uncategorized';if(!groups.has(k))groups.set(k,{name:x.category&&x.category.name||'未分类',items:[]});groups.get(k).items.push(x)});var head='<div class="calendar-preview-header"><div class="calendar-preview-category-head">活动分类</div><div class="calendar-preview-label">日程</div>'+dates.map(function(d){return '<div class="calendar-preview-date'+(d===today?' is-today':'')+'">'+d.slice(5)+'</div>'}).join('')+'</div>',body='';groups.forEach(function(g){var rows=g.items.map(function(def){var bars=(map.get(def.id)||[]).map(function(x){var s=Math.max(0,diffDays(from,x.startDate)),e=Math.min(days-1,diffDays(from,x.endDate||x.startDate));if(e<0||s>=days)return'';return '<button type="button" draggable="true" class="calendar-preview-bar" data-preview-drag-id="'+def.id+'" data-preview-occurrence-date="'+escapeHtml(x.occurrenceDate||x.startDate)+'" style="grid-row:1;grid-column:'+(s+2)+' / '+(e+3)+';background:'+(x.color||activityColor(x.name))+';font-weight:'+(x.fontBold?'900':'700')+'">'+escapeHtml(x.name)+'</button>'}).join('');return '<div class="calendar-preview-row" data-preview-row-id="'+def.id+'"><div class="calendar-preview-label" data-preview-schedule-id="'+def.id+'">'+escapeHtml(def.name)+'</div><div class="calendar-preview-days">'+dates.map(function(d){return '<div class="calendar-preview-drop" data-preview-date="'+d+'" data-preview-row="'+def.id+'"></div>'}).join('')+'</div>'+bars+'</div>'}).join('');body+='<div class="calendar-preview-category-group"><div class="calendar-preview-category-cell" style="grid-row:span '+Math.max(1,g.items.length)+'">'+escapeHtml(g.name)+'</div><div class="calendar-preview-group-rows">'+rows+'</div></div>'});host.innerHTML='<div class="calendar-preview-grid" style="--preview-days:'+days+';--preview-day-width:48px;width:'+(340+days*48)+'px">'+head+body+'</div>';syncPreviewToolbar();}
